const TOEFL_DAY_COUNT=56;
const OPIC_DAY_COUNT=13;
const UNIFIED_WORDS=[
  ...TOEFL_WORDS.map(w=>({...w,course:'toefl',courseDay:Number(w.newDay)})),
  ...OPIC_WORDS.map(w=>({...w,course:'opic',courseDay:Number(w.newDay),newDay:Number(w.newDay)+TOEFL_DAY_COUNT}))
];
const UNIFIED_DAY_META={...TOEFL_DAY_META};
Object.entries(OPIC_DAY_META).forEach(([day,meta])=>{
  UNIFIED_DAY_META[Number(day)+TOEFL_DAY_COUNT]={...meta,course:'opic',courseDay:Number(day)};
});

