function normalizedCollocationItem(item){
  if(item==null)return {en:'',ko:''};
  if(typeof item==='object'){
    const en=String(item.collocation||item.phrase||item.word||item.en||'').trim();
    const ko=String(item.meaning_ko||item.meaning||item.ko||'').trim();
    return {en:/^\[?object object\]?$/i.test(en)?'':en,ko};
  }
  const en=String(item).trim();
  return {en:/^\[?object object\]?$/i.test(en)?'':en,ko:''};
}
function normalizedCollocationsOf(w){
  const raw=(Array.isArray(w?.collocations2)&&w.collocations2.length)?w.collocations2:(w?.collocation?[w.collocation]:[]);
  const ko=Array.isArray(w?.collocationsKo)?w.collocationsKo:[];
  return raw.map((item,i)=>{
    const n=normalizedCollocationItem(item);
    const koItem=normalizedCollocationItem(ko[i]);
    return {en:n.en,ko:n.ko||koItem.ko||koItem.en||''};
  }).filter(x=>x.en);
}
