// Robust Web Speech API wrapper (Android Chrome / WebView friendly)
const APP_SETTINGS_KEY='myVocaConfigurationV1';
const APP_SETTINGS_DEFAULTS={speechRate:1.1,exampleRepeat:2,patternRepeat:1,collocationRepeat:1,synonymRepeat:1,recallDelay:3,sentenceRepeat:2,dayLoopSentenceRepeat:2,sentenceContinuous:true,sentencePause:700,wordReadRepeat:3,continuousStudyRepeat:1,quizWordRepeat:1,quizAutoNext:true,myClassAutoPlay:true,myClassSentenceRepeat:2,myClassPause:700};
function loadAppSettings(){
  try{return {...APP_SETTINGS_DEFAULTS,...JSON.parse(localStorage.getItem(APP_SETTINGS_KEY)||'{}')}}catch(e){return {...APP_SETTINGS_DEFAULTS}}
}
let appSettings=loadAppSettings();
function settingInt(key,fallback,min=1,max=10){const n=parseInt(appSettings[key],10);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):fallback}
function syncContinuousStudyRepeatControl(){
  const repeat=settingInt('continuousStudyRepeat',1,1,10);
  const el=$('autoRepeat');if(el)el.value=String(repeat);
  try{localStorage.setItem(selectedRepeatKey(),String(repeat))}catch(e){}
}
function saveAppSettings(next){appSettings={...APP_SETTINGS_DEFAULTS,...next};localStorage.setItem(APP_SETTINGS_KEY,JSON.stringify(appSettings));setSpeechRate(appSettings.speechRate);syncContinuousStudyRepeatControl();refreshHomeConfigSummary();}
async function speakQuizWordRepeated(qOrText,rate=.78){
  const text=typeof qOrText==='string'?qOrText:String(qOrText?.word||'');
  if(!text)return;
  appSettings=loadAppSettings();
  const count=settingInt('quizWordRepeat',1,1,5);
  for(let n=0;n<count;n++){
    await speakOne(text,rate,'en-US');
    if(n<count-1)await new Promise(r=>setTimeout(r,180));
  }
}
const SPEECH_RATE_KEY='myVocaSpeechRate';
let speechRate=(()=>{const saved=parseFloat(appSettings.speechRate??localStorage.getItem(SPEECH_RATE_KEY)??'1.1');return Number.isFinite(saved)?saved:1.1})();
function getSpeechRate(){return Math.max(.5,Math.min(2,Number(speechRate)||1.1));}
function setSpeechRate(value){
  const next=parseFloat(value);
  speechRate=Number.isFinite(next)?next:1.1;
  localStorage.setItem(SPEECH_RATE_KEY,String(speechRate));
  appSettings.speechRate=speechRate;
  localStorage.setItem(APP_SETTINGS_KEY,JSON.stringify(appSettings));
  stopSpeech();
}
const TTS={seq:0,voice:null,ready:false};
function ttsSupported(){return 'speechSynthesis' in window && 'SpeechSynthesisUtterance' in window}
function pickVoice(lang='en-US'){
  if(!ttsSupported())return null;
  const voices=window.speechSynthesis.getVoices()||[];
  const isKo=/^ko/i.test(lang);
  if(isKo){
    return voices.find(v=>/^ko-KR$/i.test(v.lang)&&/Google|Samsung|Microsoft/i.test(v.name))
        || voices.find(v=>/^ko(-|_)/i.test(v.lang))
        || voices.find(v=>/^ko/i.test(v.lang))
        || null;
  }
  return voices.find(v=>/^en-US$/i.test(v.lang)&&/Google|Samsung|Microsoft/i.test(v.name))
      || voices.find(v=>/^en-US$/i.test(v.lang))
      || voices.find(v=>/^en(-|_)/i.test(v.lang))
      || voices.find(v=>/^en/i.test(v.lang))
      || voices[0] || null;
}
function initTTS(){
  if(!ttsSupported()){
    const s=document.getElementById('autoStatus');
    if(s)s.textContent='이 브라우저에서는 음성 읽기를 지원하지 않습니다.';
    return false;
  }
  TTS.voice=pickVoice('en-US');
  TTS.ready=true;
  return true;
}
function unlockTTSFromGesture(){
  if(!initTTS())return;
  try{
    const u=new SpeechSynthesisUtterance(' ');
    u.lang='en-US';
    u.volume=0;
    u.rate=getSpeechRate();
    const v=pickVoice('en-US');
    if(v)u.voice=v;
    window.speechSynthesis.speak(u);
    if(window.speechSynthesis.paused)window.speechSynthesis.resume();
  }catch(e){}
}
if(ttsSupported()){
  initTTS();
  window.speechSynthesis.onvoiceschanged=()=>{TTS.voice=pickVoice('en-US');};
}
