  stopSpeech();clearSelectedProgress();AUTO.active=false;forceReleaseWakeLock();clearExactReadingFocus();updateAutoBadge();$('bar').style.width='100%';
  $('finishSummary').innerHTML=`선택한 ${AUTO.selectedDays.length}개 Day · ${deck.length}개 카드를 ${AUTO.repeats}회 자동 학습했습니다.`;
  $('finishOverlay').classList.remove('hidden');
