function goToNextQuizQuestion(){
  stopDayLoop(true);
  clearQuizAutoNext();
  stopSpeech();
  if('speechSynthesis' in window)window.speechSynthesis.cancel();
  clearSentenceRecallTimer();
  stopSentenceRepeat(true);
  quizPendingPlaybackFactory=null;
  if(quizSessionDone){resetQuizSession();return;}
  // 답을 선택하지 않았어도 문제를 건너뛸 수 있다. 건너뛴 문제는 통계에 반영하지 않는다.
  quizIndex++;
  if(quizIndex>=quizDeck.length)showQuizFinish();
  else newq();
}
function scheduleQuizAutoNext(){
  clearQuizAutoNext();
  appSettings=loadAppSettings();
  if(appSettings.quizAutoNext===false)return;
  quizAutoNextTimer=setTimeout(()=>{
    quizAutoNextTimer=null;
    if(quizAnswered&&!quizSessionDone)goToNextQuizQuestion();
  },1000);
}
let quizDeck=[], quizIndex=0, quizSessionDone=false, quizSessionWrong=[];

function updateQuizStats(w){if(!w)return;const st=quizMode==='sentence'?ensureSentenceStats(w):(stats[w.word]||{});const correct=quizMode==='sentence'?(st.sentenceCorrect||0):(st.quizCorrect||0),wrong=quizMode==='sentence'?(st.sentenceWrong||0):(st.quizWrong||0),streak=quizMode==='sentence'?(st.sentenceStreak||0):(st.quizStreak||0),total=correct+wrong;$('quizCorrectBadge').textContent='정답 '+correct+'회';$('quizWrongBadge').textContent='오답 '+wrong+'회';$('quizStreakBadge').textContent='연속 정답 '+streak+'회';$('quizAccuracyBadge').textContent='정답률 '+(total?Math.round(correct*100/total):0)+'%'}

let quizSelectedDay=1;
let quizAllWrongMode=false;

function quizFilterLabel(){
  return ({all:'전체 단어',wrong:'틀린 단어만',favorite:'모르는 단어',wrongFav:'틀린 단어 + 모르는 단어'})[quizFilterMode]||'전체 단어';
}
function applyQuizFilter(items){
  const source=[...items];
  if(quizFilterMode==='wrong')return source.filter(w=>(stats[w.word]?.quizWrong||0)>0);
  if(quizFilterMode==='favorite')return source.filter(w=>favs.includes(w.word));
  if(quizFilterMode==='wrongFav')return source.filter(w=>(stats[w.word]?.quizWrong||0)>0||favs.includes(w.word));
  return source;
}
function sentenceSourceLabel(){return sentenceSourceMode==='practice'?'실전 리딩':'학습 예문';}
function sentenceStatsKey(q){
  if(!q)return '';
  if(q.sentenceStatsKey)return q.sentenceStatsKey;
  if(q.isPracticeSentence&&q.practiceId)return '__practice__'+q.practiceId;
  return q.word||'';
}
function ensureSentenceStats(q){
  const key=sentenceStatsKey(q);
  if(!key)return {};
  if(!stats[key])stats[key]={miss:0,streak:0,lastMiss:0,lastSeen:0,quizWrong:0,quizCorrect:0,quizStreak:0,lastQuizWrong:0,studyCount:0,reviewStep:0,dueAt:0};
  const st=stats[key];
  if(typeof st.sentenceWrong!=='number')st.sentenceWrong=0;
  if(typeof st.sentenceCorrect!=='number')st.sentenceCorrect=0;
  if(typeof st.sentenceStreak!=='number')st.sentenceStreak=0;
  if(typeof st.lastSentenceWrong!=='number')st.lastSentenceWrong=0;
  return st;
}
function isWeakSentence(q){
  const st=ensureSentenceStats(q);
  return (st.sentenceWrong||0)>0 && (st.sentenceStreak||0)<2;
}
function sentenceFilterLabel(){return quizFilterMode==='wrong'?'틀린 문장':'전체 문장';}
function syncSentenceSourceUI(){
  const bar=$('sentenceSourceBar');if(bar)bar.classList.toggle('show',quizMode==='sentence');
  const ex=$('sentenceSourceExample'),pr=$('sentenceSourcePractice');
  if(ex)ex.classList.toggle('active',sentenceSourceMode==='example');
  if(pr)pr.classList.toggle('active',sentenceSourceMode==='practice');
  const filter=$('quizFilterMode');
  if(filter){
    if(quizMode==='sentence'){
      const current=(quizFilterMode==='wrong')?'wrong':'all';
      filter.disabled=false;
      filter.innerHTML='<option value="all">전체 문장</option><option value="wrong">틀린 문장</option>';
      filter.value=current;
      quizFilterMode=current;
    }else{
      const current=['all','wrong','favorite','wrongFav'].includes(quizFilterMode)?quizFilterMode:'all';
      filter.disabled=false;
      filter.innerHTML='<option value="all">전체 단어</option><option value="wrong">틀린 단어만</option><option value="favorite">모르는 단어</option><option value="wrongFav">틀린 단어 + 모르는 단어</option>';
      filter.value=current;
    }
  }
}
function quizScopeLabel(){
  const scope=quizAllWrongMode ? '전체 Day 오답' : dayDisplayLabel(quizSelectedDay);
  if(quizMode==='sentence')return `${scope} · ${sentenceSourceLabel()} · ${sentenceFilterLabel()}`;
  return `${scope} · ${quizFilterLabel()}`;
}
function updateQuizFilterCount(){
  const el=document.getElementById('quizFilterCount');
  if(!el)return;
  if(quizMode==='sentence'){
    const base=sentenceSourceMode==='practice'
      ? practiceSentenceCardsMinimal([quizSelectedDay])
      : ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay));
    const count=quizFilterMode==='wrong'?base.filter(isWeakSentence).length:base.length;
    el.textContent=count+'문장';
    return;
  }
  const base=quizAllWrongMode
    ? ALL_WORDS.filter(w=>(stats[w.word]?.quizWrong||0)>0)
    : ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay));
  el.textContent=applyQuizFilter(base).length+'개';
}

function updateQuizDayNav(){
  const btn=$('quizAllWrongBtn');
  const label=$('quizDayLabel');
  if(!btn||!label)return;
  btn.classList.toggle('active',quizAllWrongMode);
  btn.disabled=quizMode==='favorite'||quizMode==='sentence';
  btn.textContent=quizMode==='favorite'?'⭐ DAY 모르는 단어 선택':quizMode==='sentence'?'문장 말하기는 퀴즈 대상에서 선택':(quizAllWrongMode?'↩ 현재 Day로 돌아가기':'🔥 전체 Day 오답');

  if(quizAllWrongMode){
    const wrongCount=ALL_WORDS.filter(w=>(stats[w.word]?.quizWrong||0)>0).length;
    label.innerHTML=`<b>전체 Day 오답</b><span>${wrongCount}개</span>`;
  }else{
    const dayWords=ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay));
    const wrongCount=dayWords.filter(w=>(stats[w.word]?.quizWrong||0)>0).length;
    label.innerHTML=`<b>${dayDisplayLabel(quizSelectedDay)}</b><span>${dayWords.length}개 · 오답 ${wrongCount}개</span>`;
  }

  $('quizPrevDay').disabled=quizSelectedDay<=1;
  $('quizNextDay').disabled=quizSelectedDay>=currentCfg().days;
  updateQuizFilterCount();
}

function setQuizDay(day){
  stopSpeech();
  if('speechSynthesis' in window) window.speechSynthesis.cancel();
  quizAllWrongMode=false;
  const maxDay=currentCfg().days;
  quizSelectedDay=Math.max(1,Math.min(maxDay,Number(day)||1));
  updateQuizDayNav();
  buildQuizDeck();
  quizAnswered=false;
  newq();
}

function showAllWrongQuiz(){
  stopSpeech();
  if('speechSynthesis' in window) window.speechSynthesis.cancel();

  if(quizAllWrongMode){
    quizAllWrongMode=false;
    quizSelectedDay=currentDay;
  }else{
    quizAllWrongMode=true;
  }

  updateQuizDayNav();
  buildQuizDeck();
  quizAnswered=false;
  newq();
}

function quizPool(){
  const base=quizAllWrongMode
    ? ALL_WORDS.filter(w=>(stats[w.word]?.quizWrong||0)>0)
    : ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay));
  return applyQuizFilter(base);
}

function buildQuizDeck(){
  const pool=quizPool();
  const lexicalEligible=pool.filter(w=>fallbackSynonymsOf(w).length||antonymsOf(w).length);
  if(quizMode==='sentence'){
    quizAllWrongMode=false;
    let sentencePool=sentenceSourceMode==='practice'
      ? practiceSentenceCardsMinimal([quizSelectedDay])
      : ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay));
    sentencePool.forEach(q=>ensureSentenceStats(q));
    if(quizFilterMode==='wrong'){
      sentencePool=sentencePool.filter(isWeakSentence).sort((a,b)=>{
        const sa=ensureSentenceStats(a),sb=ensureSentenceStats(b);
        return (sb.sentenceWrong||0)-(sa.sentenceWrong||0)||(sb.lastSentenceWrong||0)-(sa.lastSentenceWrong||0)||(Number(a.newNo)||0)-(Number(b.newNo)||0);
      });
    }else{
      sentencePool=sentencePool.sort((a,b)=>(Number(a.newDay)||0)-(Number(b.newDay)||0)||(Number(a.newNo)||0)-(Number(b.newNo)||0)||(Number(a.originalNo)||0)-(Number(b.originalNo)||0));
    }
    quizDeck=sentencePool;
  }else{
    quizDeck = quizMode==='lexical' ? shuffleDeck(lexicalEligible) : shuffleDeck(pool);
  }
  quizIndex = 0;
  quizSessionDone = false;
  quizSessionWrong = [];
  updateQuizFilterCount();
}

function updateQuizProgress(){
  const total = quizDeck.length || 0;
  const current = total ? Math.min(quizIndex+1,total) : 0;
  $('idx').textContent = current;
  $('total').textContent = total;
  $('bar').style.width = total ? (current/total*100)+'%' : '0%';
}

function restoreLearnProgress(){
  $('idx').textContent=i+1;
  $('total').textContent=deck.length;
  $('bar').style.width=(i/deck.length*100)+'%';
}


let dayLoopActive=false,dayLoopToken=0,dayLoopRound=0,dayLoopIndex=-1,dayLoopFocusIndex=-1;let dayLoopVisibleCards=new Set();

function dayLoopCards(){
  return quizDeck.filter(q=>q&&q.isPracticeSentence&&sentenceText(q));
}

function updateDayLoopFocusUI(){
  document.querySelectorAll('.dayLoopSentenceBtn').forEach((btn,i)=>{
    const focused=i===dayLoopFocusIndex;
    btn.classList.toggle('focused',focused);
    btn.setAttribute('aria-pressed',String(focused));
    btn.innerHTML=`<span>Sentence ${i+1}</span><span class="infinityIcon">∞</span>${focused?'<span>집중</span>':''}`;
  });
  document.querySelectorAll('.dayLoopCard').forEach((card,i)=>card.classList.toggle('focused',i===dayLoopFocusIndex));
}

function stopDayLoop(cancelVoice=true,clearFocus=true){
  dayLoopActive=false;dayLoopToken++;dayLoopIndex=-1;
  if(clearFocus)dayLoopFocusIndex=-1;
  if(cancelVoice){stopSpeech();if('speechSynthesis' in window)window.speechSynthesis.cancel();}
  const b=$('dayLoopToggle');if(b){b.classList.remove('active');b.textContent='🔁 반복 듣기 OFF';}
  updateDayLoopFocusUI();
  const s=$('dayLoopStatus');if(s)s.textContent=dayLoopRound?`${dayLoopRound}회 반복 · 일시정지`:'반복 듣기 일시정지';
}



function highlightKoreanPracticeText(q){
  const text=recallText(sentenceKo(q));
  if(!text)return '';
  const marks=[];
  const add=(surface,cls)=>{
    surface=String(surface||'').trim();
    if(!surface)return;
    let start=0;
    while(true){
      const i=text.indexOf(surface,start);
      if(i<0)break;
      marks.push({start:i,end:i+surface.length,cls});
      start=i+Math.max(1,surface.length);
    }
  };
  const addNested=(nested,fallback,cls)=>{
    if(Array.isArray(nested)&&nested.length){
      nested.forEach(group=>{
        const parts=Array.isArray(group)?group:[group];
        parts.forEach(x=>add(x,cls));
      });
    }else{
      (fallback||[]).forEach(x=>add(x,cls));
    }
  };
  addNested(q?.practicePatternKoSegments,q?.practicePatternKoSurfaces,'koBasePattern');
  addNested(q?.practiceExtraPatternKoSegments,q?.practiceExtraPatternKoSurfaces,'koExtraPattern');
  (q?.targetWordKoSurfaces||[]).forEach(x=>add(x,'koTargetWord'));

  const priority={koBasePattern:3,koExtraPattern:2,koTargetWord:1};
  marks.sort((a,b)=>a.start-b.start || (priority[b.cls]||0)-(priority[a.cls]||0) || (b.end-a.end));
  const accepted=[];
  for(const m of marks){
    const oi=accepted.findIndex(a=>m.start<a.end&&m.end>a.start);
    if(oi>=0){
      if((priority[m.cls]||0)>(priority[accepted[oi].cls]||0))accepted[oi]=m;
      continue;
    }
    accepted.push(m);
  }
  accepted.sort((a,b)=>a.start-b.start);
  let pos=0,html='';
  for(const m of accepted){
    html+=recallEscape(text.slice(pos,m.start));
    html+=`<span class="${m.cls}">${recallEscape(text.slice(m.start,m.end))}</span>`;
    pos=m.end;
  }
  html+=recallEscape(text.slice(pos));
  return html;
}
function setDayLoopCardVisible(index,visible){
  const cards=dayLoopCards();
  const q=cards[index];if(!q)return;
  if(visible)dayLoopVisibleCards.add(index);else dayLoopVisibleCards.delete(index);
  const sentenceEl=$('dayLoopSentence'+index);
  if(sentenceEl)sentenceEl.innerHTML=visible?sentenceHighlightedHtml(q):sentenceMaskedHtml(q);
  const btn=$('dayLoopViewBtn'+index);
  if(btn){
    btn.classList.toggle('active',visible);
    btn.textContent=visible?'🙈 문장 숨기기':'👁 문장 보기';
    btn.setAttribute('aria-pressed',String(visible));
  }
}
function renderDayLoopTraining(autoStart=true){
  const cards=dayLoopCards();
  if(!cards.length)return false;
  dayLoopFocusIndex=-1;dayLoopVisibleCards=new Set();
  $('qw').textContent=`DAY ${quizSelectedDay} Loop Training`;
  $('quizMeta').textContent='50% 이상 가린 실전 문장을 먼저 떠올린 뒤 완전한 문장을 들어보세요.';
  const perSentence=settingInt('dayLoopSentenceRepeat',2,1,5);
  $('opts').innerHTML=`<div class="dayLoopWrap">
    <div class="dayLoopHero">
      <div class="dayLoopHeroTop"><div><div class="dayLoopTitle">🎧 Day Loop Training</div><div class="dayLoopSub">50% 가리기 · 문장당 ${perSentence}회 · DAY 전체 무한 반복</div></div><button id="dayLoopToggle" class="dayLoopToggle ${autoStart?'active':''}" type="button">🔁 반복 듣기 ${autoStart?'ON':'OFF'}</button></div>
      <div id="dayLoopStatus" class="dayLoopStatus">전체 ${cards.length}문장 · Sentence 버튼의 ∞를 누르면 해당 문장만 무한 반복</div>
    </div>
    <div id="dayLoopList" class="dayLoopList">${cards.map((q,i)=>`<div class="dayLoopCard" id="dayLoopCard${i}">
      <div class="dayLoopCardTop">
        <div class="dayLoopNo"><button class="dayLoopSentenceBtn" data-day-loop-focus="${i}" type="button" aria-pressed="false"><span>Sentence ${i+1}</span><span class="infinityIcon">∞</span></button></div>
        <button id="dayLoopViewBtn${i}" class="dayLoopViewBtn" data-day-loop-view="${i}" type="button" aria-pressed="false">👁 문장 보기</button>
      </div>
      <div class="dayLoopKo dayLoopKoRecall">${highlightKoreanPracticeText(q)}</div>
      <div class="dayLoopSentence" id="dayLoopSentence${i}">${sentenceMaskedHtml(q)}</div>
    </div>`).join('')}</div>
    <div class="dayLoopFooter"><button id="dayLoopTop" type="button">↑ 맨 위로</button><button id="dayLoopRestart" type="button">↻ 처음부터</button></div>
  </div>`;
  $('quizFeedback').className='quizFeedback hidden';
  $('nextq').classList.add('hidden');$('prevq').classList.add('hidden');

  $('dayLoopToggle').onclick=()=>{
    if(dayLoopActive)stopDayLoop(true,true);
    else startDayLoopTraining(Math.max(0,dayLoopIndex),true);
  };
  $('dayLoopTop').onclick=()=>document.getElementById('dayLoopCard0')?.scrollIntoView({behavior:'smooth',block:'center'});
  $('dayLoopRestart').onclick=()=>{stopDayLoop(true,true);startDayLoopTraining(0,true)};

  document.querySelectorAll('[data-day-loop-focus]').forEach(btn=>{
    btn.onclick=()=>{
      const target=Number(btn.dataset.dayLoopFocus);
      if(dayLoopFocusIndex===target){
        // Same button again: release infinite repeat and resume normal loop from NEXT sentence.
        const next=(target+1)%cards.length;
        dayLoopFocusIndex=-1;
        dayLoopToken++;
        stopSpeech();if('speechSynthesis' in window)window.speechSynthesis.cancel();
        updateDayLoopFocusUI();
        startDayLoopTraining(next,false);
      }else{
        // Another sentence: current focus is automatically released and new sentence becomes infinite focus.
        startDayLoopFocused(target);
      }
    };
  });

  // Per-card show/hide only changes the text rendering. It never interrupts TTS.
  document.querySelectorAll('[data-day-loop-view]').forEach(btn=>{
    btn.onclick=()=>{
      const target=Number(btn.dataset.dayLoopView);
      setDayLoopCardVisible(target,!dayLoopVisibleCards.has(target));
    };
  });

  if(autoStart)setTimeout(()=>startDayLoopTraining(0,true),180);
  return true;
}

async function playDayLoopSentence(q,idx,token,repeatNo,totalRepeats,focused=false){
  if(!dayLoopActive||token!==dayLoopToken)return false;
  dayLoopIndex=idx;
  document.querySelectorAll('.dayLoopCard.active').forEach(el=>el.classList.remove('active'));
  const card=$('dayLoopCard'+idx);
  if(card){card.classList.add('active');card.scrollIntoView({behavior:'smooth',block:'center'});}
  const status=$('dayLoopStatus');
  if(status)status.textContent=focused
    ?`Sentence ${idx+1} ∞ 집중 반복 · 해제하려면 같은 Sentence 버튼을 다시 누르세요`
    :`${dayLoopRound}회째 · ${idx+1}/${dayLoopCards().length} · ${repeatNo}/${totalRepeats} · 먼저 말해보세요`;

  const recallWait=Math.max(900,Math.min(3000,Number(appSettings.sentencePause)||1500));
  await new Promise(r=>setTimeout(r,recallWait));
  if(!dayLoopActive||token!==dayLoopToken)return false;
  if(status&&!focused)status.textContent=`${dayLoopRound}회째 · ${idx+1}/${dayLoopCards().length} · ${repeatNo}/${totalRepeats} · 정답 듣기`;
  const text=sentenceText(q);
  if(text)await speakComplete(text,getSpeechRate(),'en-US');
  if(!dayLoopActive||token!==dayLoopToken)return false;
  await new Promise(r=>setTimeout(r,Math.max(250,Math.min(1800,Number(appSettings.sentencePause)||700))));
  return dayLoopActive&&token===dayLoopToken;
}

async function startDayLoopTraining(startIndex=0,newRound=false){
  const cards=dayLoopCards();if(!cards.length)return;
  // Invalidate previous loop but preserve the new normal-loop state.
  dayLoopToken++;
  stopSpeech();if('speechSynthesis' in window)window.speechSynthesis.cancel();
  dayLoopActive=true;dayLoopFocusIndex=-1;if(newRound)dayLoopRound=0;
  updateDayLoopFocusUI();
  const token=++dayLoopToken;
  const btn=$('dayLoopToggle');if(btn){btn.classList.add('active');btn.textContent='🔁 반복 듣기 ON';}
  let idx=Math.max(0,Math.min(startIndex,cards.length-1));
  while(dayLoopActive&&token===dayLoopToken&&dayLoopFocusIndex<0){
    dayLoopRound++;
    for(;idx<cards.length;idx++){
      if(!dayLoopActive||token!==dayLoopToken||dayLoopFocusIndex>=0)return;
      const repeats=settingInt('dayLoopSentenceRepeat',2,1,5);
      for(let r=1;r<=repeats;r++){
        if(!await playDayLoopSentence(cards[idx],idx,token,r,repeats,false))return;
      }
    }
    idx=0;
  }
}

async function startDayLoopFocused(targetIndex){
  const cards=dayLoopCards();if(!cards.length||!cards[targetIndex])return;
  dayLoopToken++;
  stopSpeech();if('speechSynthesis' in window)window.speechSynthesis.cancel();
  dayLoopActive=true;dayLoopFocusIndex=targetIndex;dayLoopIndex=targetIndex;
  updateDayLoopFocusUI();
  const token=++dayLoopToken;
  const btn=$('dayLoopToggle');if(btn){btn.classList.add('active');btn.textContent='🔁 반복 듣기 ON';}
  let focusRepeat=0;
  while(dayLoopActive&&token===dayLoopToken&&dayLoopFocusIndex===targetIndex){
    focusRepeat++;
    const status=$('dayLoopStatus');
    if(status)status.textContent=`Sentence ${targetIndex+1} ∞ 집중 반복 · ${focusRepeat}회째 · 같은 버튼을 누르면 해제`;
    if(!await playDayLoopSentence(cards[targetIndex],targetIndex,token,focusRepeat,focusRepeat,true))return;
  }
}

function showQuizFinish(){
  quizSessionDone=true;
  quizCurrent=null;
  const total=quizDeck.length;
  const wrongCount=quizSessionWrong.length;
  $('qw').textContent='퀴즈 완료 🎉';
  $('quizMeta').textContent=`${wrongCount}/${total}개 틀렸습니다.`;

  if(wrongCount){
    $('opts').innerHTML=`
      <div style="margin-top:16px;text-align:left">
        <div style="font-size:13px;font-weight:900;color:#667085;margin-bottom:9px">이번 퀴즈에서 틀린 단어</div>
        ${quizSessionWrong.map((x,n)=>`
          <div style="padding:13px 14px;margin-bottom:8px;border:1px solid #e5e7eb;border-radius:14px;background:#fff">
            <div style="display:flex;align-items:flex-start;gap:10px">
              <span style="min-width:24px;color:#98a2b3;font-weight:800">${n+1}</span>
              <div>
                <div style="font-size:19px;font-weight:900">${x.word}</div>
                <div style="margin-top:4px;color:#475467;line-height:1.45">${x.meaning}</div>
              </div>
            </div>
          </div>`).join('')}
      </div>`;
    $('quizFeedback').className='quizFeedback no';
    $('quizFeedback').innerHTML=`정답 ${total-wrongCount}개 · 오답 ${wrongCount}개`;
  }else{
    $('opts').innerHTML='';
    $('quizFeedback').className='quizFeedback ok';
    $('quizFeedback').innerHTML=`${total}개 모두 맞았습니다! 🎉`;
  }

  $('nextq').textContent='다시하기';
  $('nextq').classList.remove('hidden');
  updateQuestionNavButtons();
  $('idx').textContent=total;
  $('total').textContent=total;
  $('bar').style.width='100%';
  if(quizMode==='sentence'&&sentenceSourceMode==='practice'&&total>0){
    renderDayLoopTraining(true);
  }
}

function recallText(value){return decodeDataEntities(value==null?'':String(value));}
function recallEscape(value){return recallText(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));}

function clearSentenceRecallTimer(){
  if(sentenceRecallTimer){clearTimeout(sentenceRecallTimer);sentenceRecallTimer=null;}
  sentenceRepeatToken++;
}

function stopSentenceRepeat(cancelVoice=true){
  sentenceRepeatToken++;
  if(cancelVoice){
    stopSpeech();
    if('speechSynthesis' in window)window.speechSynthesis.cancel();
  }
}

async function startSentenceContinuousRepeat(q,stage=1){
  const myToken=++sentenceRepeatToken;
  const reads=settingInt('sentenceRepeat',2,1,5);
  const continuous=appSettings.sentenceContinuous!==false;
  const pause=Math.max(100,Math.min(5000,Number(appSettings.sentencePause)||700));
  do{
    for(let n=0;n<reads;n++){
      if(myToken!==sentenceRepeatToken||quizMode!=='sentence'||quizCurrent!==q||sentenceRecallStage!==stage||quizSessionDone)return;
      if(stage===2&&!sentenceStage2Repeat)return;
      await speakSentenceOnce(q);
      if(myToken!==sentenceRepeatToken||quizMode!=='sentence'||quizCurrent!==q||sentenceRecallStage!==stage||quizSessionDone)return;
      sentenceIncrementCount(q);
      if(n<reads-1)await new Promise(r=>setTimeout(r,420));
    }
    if(!continuous)return;
    await new Promise(r=>setTimeout(r,pause));
  }while(myToken===sentenceRepeatToken&&quizMode==='sentence'&&quizCurrent===q&&sentenceRecallStage===stage&&!quizSessionDone&&(stage!==2||sentenceStage2Repeat));
}

function setQuizMode(mode){
  stopDayLoop(true);
  clearQuizAutoNext();
  const nextMode=['choice','recall','sentence','favorite','lexical'].includes(mode)?mode:'choice';
  if(quizMode===nextMode)return;
  clearSentenceRecallTimer();
  quizPendingPlaybackFactory=null;
  stopSpeech();
  if('speechSynthesis' in window)window.speechSynthesis.cancel();
  quizMode=nextMode;
  ['Choice','Recall','Sentence','Favorite','Lexical'].forEach(name=>{
    const el=$('quizMode'+name);if(!el)return;
    const active=quizMode===name.toLowerCase();
    el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));
  });
  $('quiz').classList.toggle('selector-mode',quizMode==='favorite');
  $('recallGuide').classList.toggle('hidden',quizMode==='choice');
  if(quizMode==='recall')$('recallGuide').textContent='문제를 보고 답을 소리 내어 말한 뒤 정답을 확인하세요. 맞았어요/오답 기록은 기존 객관식 카운터와 공유됩니다.';
  if(quizMode==='sentence')$('recallGuide').textContent='문장 소스를 선택하세요. 1단계 전체 문장 반복 듣기·따라 말하기 → 2단계 핵심 표현과 50% 이상 빈칸 말하기 → 3단계 한글만 보고 전체 문장 말하기 순서입니다.';
  if(quizMode==='favorite')$('recallGuide').textContent='DAY 전체 단어를 먼저 훑어보고 모르는 단어를 체크하세요. 체크한 단어는 학습 화면의 모르는 단어와 즉시 연동됩니다.';
  if(quizMode==='lexical')$('recallGuide').textContent='유의어 뜻 맞추기·같은 뜻 찾기·패러프레이징에 사용된 유의어 찾기·반의어 찾기를 섞어서 연습합니다. 등록된 데이터가 있는 문제만 출제됩니다.';
  $('quizDirection').disabled=quizMode==='sentence'||quizMode==='favorite'||quizMode==='lexical';
  syncSentenceSourceUI();
  updateQuizPlaybackButton();
  resetQuizSession();
}

function quizExampleText(q){
  return recallText(q?.example||q?.sentence||q?.example_en||q?.sentence_en||'').trim();
}
function quizTranslationText(q){
  return recallText(q?.translation||q?.exampleTranslation||q?.example_ko||q?.sentence_ko||q?.translation_ko||'').trim();
}

function recallSpeakAnswer(q){
  if(!q)return Promise.resolve();
  stopSpeech();
  if('speechSynthesis' in window)window.speechSynthesis.cancel();
  return (async()=>{
    await speakQuizWordRepeated(q,.78);
    await new Promise(r=>setTimeout(r,260));
    const example=quizExampleText(q);
    if(example)await speakOne(example,.84);
  })();
}

async function scheduleQuizAutoNextAfterPlayback(playbackPromise,q){
  clearQuizAutoNext();
  appSettings=loadAppSettings();
  if(appSettings.quizAutoNext===false||!quizPlaybackEnabled)return;
  try{await Promise.resolve(playbackPromise)}catch(e){}
  if(!quizPlaybackEnabled||quizCurrent!==q||!quizAnswered||quizSessionDone)return;
  quizAutoNextTimer=setTimeout(()=>{
    quizAutoNextTimer=null;
    if(quizPlaybackEnabled&&quizCurrent===q&&quizAnswered&&!quizSessionDone)goToNextQuizQuestion();
  },250);
}

function choiceResultPlayback(q,selectedObj,isCorrect){
  stopSpeech();
  if('speechSynthesis' in window)window.speechSynthesis.cancel();
  return (async()=>{
    if(!isCorrect&&selectedObj&&selectedObj.word){
      await speakOne(selectedObj.word,.78);
      await new Promise(r=>setTimeout(r,220));
    }
    await speakQuizWordRepeated(q,.78);
    const example=quizExampleText(q);
    if(example){
      await new Promise(r=>setTimeout(r,280));
      await speakOne(example,.84);
    }
  })();
}

function recordRecallResult(q,isCorrect){
  if(quizAnswered||!q)return;
  quizAnswered=true;
  const isSentence=quizMode==='sentence';
  const st=isSentence?ensureSentenceStats(q):stats[q.word];
  if(isCorrect){
    if(isSentence){
      st.sentenceCorrect=(st.sentenceCorrect||0)+1;
      st.sentenceStreak=(st.sentenceStreak||0)+1;
      $('quizFeedback').className='quizFeedback ok';
      $('quizFeedback').innerHTML=st.sentenceStreak>=2?'맞았어요! 연속 2회 정답으로 틀린 문장 목록에서 졸업했습니다.':'맞았어요! 한 번 더 연속으로 맞히면 틀린 문장 목록에서 졸업합니다.';
    }else{
      st.quizCorrect=(st.quizCorrect||0)+1;
      st.quizStreak=(st.quizStreak||0)+1;
      applyQuizReviewResult(st,true);
      $('quizFeedback').className='quizFeedback ok';
      $('quizFeedback').innerHTML='맞았어요! 기존 객관식과 같은 정답 카운터에 반영했습니다.';
    }
  }else{
    if(isSentence){
      st.sentenceWrong=(st.sentenceWrong||0)+1;
      st.sentenceStreak=0;
      st.lastSentenceWrong=Date.now();
      $('quizFeedback').className='quizFeedback no';
      $('quizFeedback').innerHTML='오답으로 기록했습니다. 이 문장은 틀린 문장 집중 학습 대상에 포함됩니다.';
    }else{
      st.quizWrong=(st.quizWrong||0)+1;
      st.quizStreak=0;
      st.lastQuizWrong=Date.now();
      applyQuizReviewResult(st,false);
      $('quizFeedback').className='quizFeedback no';
      $('quizFeedback').innerHTML='오답으로 기록했습니다. 기존 객관식과 같은 오답 카운터에 반영했습니다.';
    }
    if(!quizSessionWrong.some(x=>x.word===q.word))quizSessionWrong.push({word:q.word,meaning:q.meaning});
  }
  document.querySelectorAll('#opts .recallAction').forEach(btn=>btn.disabled=true);
  $('nextq').classList.remove('hidden');
  save();
  updateQuizStats(q);
  quizPendingPlaybackFactory=()=>quizMode==='sentence'?speakSentenceOnce(q):recallSpeakAnswer(q);
  startCurrentQuizResultPlayback();
}

function showRecallAnswer(q,recordWrongNow=false){
  if(!q)return;
  $('opts').innerHTML=`
    <div class="recallAnswerCard">
      <div class="recallAnswerWordRow">
        <div class="recallAnswerWord">${recallEscape(q.word||'')}</div>
        <div class="recallAnswerWordActions">
          <button id="recallWordSpeakBtn" class="recallWordMiniBtn" type="button" aria-label="${recallEscape(q.word||'')} 발음 듣기" title="단어 발음 듣기">🔊</button>
          <button id="recallWordCompareBtn" class="recallWordMiniBtn compare" type="button" aria-label="${recallEscape(q.word||'')} 비슷한 단어 비교" title="비슷한 단어 비교">⇄</button>
        </div>
      </div>
      <div class="recallAnswerMeaning">${recallEscape(q.meaning||'')}</div>
      ${quizExampleText(q)?`<div class="recallAnswerExample">${recallEscape(quizExampleText(q))}</div>`:''}
      ${quizTranslationText(q)?`<div class="recallAnswerTranslation">${recallEscape(quizTranslationText(q))}</div>`:''}
      <button id="recallListenAnswer" class="recallListenBtn" type="button">🔊 정답과 예문 듣기</button>
    </div>
    <div class="recallActions">
      <button id="recallCorrectBtn" class="recallAction recallCorrect" type="button">맞았어요</button>
      <button id="recallWrongBtn" class="recallAction recallWrong" type="button">오답</button>
    </div>`;
  $('recallWordSpeakBtn').onclick=()=>{stopSpeech();speakQuizWordRepeated(q,.82)};
  $('recallWordCompareBtn').onclick=()=>{if(typeof window.openQuickCompare==='function')window.openQuickCompare(q)};
  $('recallListenAnswer').onclick=()=>recallSpeakAnswer(q);
  $('recallCorrectBtn').onclick=()=>recordRecallResult(q,true);
  $('recallWrongBtn').onclick=()=>recordRecallResult(q,false);
  recallSpeakAnswer(q);
  if(recordWrongNow)recordRecallResult(q,false);
}

function newRecallQuestion(){
  if(!quizDeck.length)buildQuizDeck();
  if(!quizDeck.length){
    $('qw').textContent='완료 🎉';
    $('quizMeta').textContent=quizScopeLabel()+' 조건에 해당하는 문제가 없습니다.';
    $('opts').innerHTML='';
    $('quizFeedback').className='quizFeedback hidden';
    $('nextq').textContent='다시하기';
    $('nextq').classList.remove('hidden');
    $('idx').textContent='0';$('total').textContent='0';$('bar').style.width='0%';
    quizSessionDone=true;return;
  }
  if(quizIndex>=quizDeck.length){showQuizFinish();return;}

  const direction=$('quizDirection').value;
  $('quiz').classList.toggle('ko-en-mode',direction==='koEn');
  $('quizFeedback').className='quizFeedback hidden';
  $('quizFeedback').textContent='';
  $('nextq').textContent='다음 →';
  $('nextq').classList.remove('hidden');
  quizAnswered=false;
  quizPendingPlaybackFactory=null;
  quizCurrent=quizDeck[quizIndex];
  updateQuizProgress();
  const q=quizCurrent;
  updateQuizStats(q);

  if(direction==='koEn'){
    $('qw').textContent=recallText(q.meaning||'');
    $('quizMeta').textContent=`${quizScopeLabel()} · 뜻을 보고 영어 단어를 말하세요 · ${quizIndex+1}/${quizDeck.length}`;
  }else{
    $('qw').textContent=recallText(q.word||'');
    $('quizMeta').textContent=`${quizScopeLabel()} · 영어 단어를 보고 뜻을 말하세요 · ${quizIndex+1}/${quizDeck.length}`;
  }
  $('opts').innerHTML=`
    <div class="recallActions">
      <button id="recallShowBtn" class="recallAction recallShow" type="button">정답 보기</button>
      <button id="recallMissNowBtn" class="recallAction recallMissNow" type="button">오답</button>
    </div>`;
  $('recallShowBtn').onclick=()=>showRecallAnswer(q,false);
  $('recallMissNowBtn').onclick=()=>showRecallAnswer(q,true);

  if(hasStarted&&direction==='enKo'){
    if('speechSynthesis' in window)window.speechSynthesis.cancel();
    speakQuizWordRepeated(q,.78);
  }
}

function sentenceText(q,variant=sentenceRecallVariant){
  if(variant==='paraphrase')return recallText(q?.paraphrase||'').trim();
  return recallText(q?.example||q?.sentence||q?.word||'').trim();
}
function sentenceKo(q,variant=sentenceRecallVariant){
  if(variant==='paraphrase')return recallText(q?.paraphraseTranslation||q?.translation||q?.meaning||'').trim();
  return recallText(q?.translation||q?.exampleTranslation||q?.meaning||'').trim();
}
function sentencePattern(q,variant=sentenceRecallVariant){
  if(variant==='paraphrase')return recallText(q?.synonymUsed||'').trim();
  if(q?.isPracticeSentence&&Array.isArray(q.practicePatterns))return q.practicePatterns.filter(Boolean).join(' · ');
  return recallText(q?.pattern||q?.used_pattern||q?.collocation||q?.phrase||'').trim();
}
function sentencePatternMeaning(q,variant=sentenceRecallVariant){
  if(q?.isPracticeSentence&&Array.isArray(q.practicePatternMeanings))return q.practicePatternMeanings.filter(Boolean).join(' · ');
  if(variant==='paraphrase'){
    const target=recallText(q?.synonymUsed||'').trim().toLowerCase();
    const list=Array.isArray(q?.synonyms)?q.synonyms:[];
    const hit=list.find(x=>Array.isArray(x)&&recallText(x[0]).trim().toLowerCase()===target);
    if(hit&&hit[1])return recallText(hit[1]).trim();
  }
  return recallText(q?.pattern_ko_recommended||q?.patternMeaning||q?.pattern_ko||'').trim();
}
function blankWordsHtml(raw,extraClass=''){
  const text=recallText(raw);
  const tokens=text.match(/\s+|[A-Za-z0-9]+(?:['’\-][A-Za-z0-9]+)*|[^A-Za-z0-9\s]+/g)||[text];
  return tokens.map(tok=>{
    if(/^\s+$/.test(tok))return tok;
    if(/^[A-Za-z0-9]/.test(tok)){
      const width=Math.max(2.2,Math.min(7.5,tok.length*.56));
      return `<span class="recallBlank ${extraClass}" style="min-width:${width}em" aria-label="빈칸">${recallEscape(tok)}</span>`;
    }
    return recallEscape(tok);
  }).join('');
}
function hasParaphraseSentence(q){
  const para=recallText(q?.paraphrase||'').trim();
  const base=recallText(q?.example||'').trim();
  return !!para && para.toLowerCase()!==base.toLowerCase();
}
function sentenceVariantLabel(){return sentenceRecallVariant==='paraphrase'?'패러프레이징 문장':'기본 문장';}

function sentenceMaskedHtml(q){
  const text=sentenceText(q);
  if(!text)return '<span class="patternEmpty">등록된 학습 문장이 없습니다.</span>';
  const pattern=sentencePattern(q);
  const word=recallText(q?.word||'').trim();
  const practicePatterns=q?.isPracticeSentence&&Array.isArray(q.practicePatterns)?q.practicePatterns.filter(Boolean):[];
  const practiceExtraSurfaces=q?.isPracticeSentence&&Array.isArray(q.practiceExtraPatternSurfaces)?q.practiceExtraPatternSurfaces.filter(Boolean):[];
  const practiceWords=q?.isPracticeSentence&&Array.isArray(q.targetWords)?q.targetWords.filter(Boolean):[];
  const patternRanges=q?.isPracticeSentence?practicePatterns.flatMap(x=>collectFlexiblePracticePatternRanges(text,x)):(pattern?collectHighlightRanges(text,pattern):[]);
  const extraPatternRanges=q?.isPracticeSentence?practiceExtraSurfaces.flatMap(x=>collectHighlightRanges(text,x)):[];
  const wordRanges=q?.isPracticeSentence?practiceWords.flatMap(x=>collectHighlightRanges(text,x)):(word?collectHighlightRanges(text,word):[]);

  // 문장 내 영어 단어를 모두 토큰화한다. 2단계에서는 최소 50%를 가린다.
  const tokenRe=/[A-Za-z0-9]+(?:['’\-][A-Za-z0-9]+)*/g;
  const tokens=[];
  let m;
  while((m=tokenRe.exec(text))!==null){
    tokens.push({start:m.index,end:m.index+m[0].length,text:m[0],index:tokens.length});
  }
  if(!tokens.length)return recallEscape(text);

  const overlaps=(token,ranges)=>ranges.some(([a,b])=>token.start<b&&token.end>a);
  const selected=new Set();
  tokens.forEach((t,idx)=>{
    if(overlaps(t,patternRanges)||overlaps(t,extraPatternRanges)||overlaps(t,wordRanges))selected.add(idx);
  });

  const target=Math.ceil(tokens.length*0.5);
  const stopWords=new Set([
    'a','an','the','and','or','but','so','if','then','than','as','at','by','for','from','in','into','of','on','to','up','with',
    'i','you','he','she','it','we','they','me','him','her','us','them','my','your','his','our','their','this','that','these','those',
    'am','is','are','was','were','be','been','being','do','does','did','have','has','had','will','would','can','could','may','might','must','shall','should',
    'not','no','yes','there','here','what','which','who','whom','whose','when','where','why','how','just','very','too'
  ]);

  // 핵심어를 우선하되 문장 앞·중간·뒤에 균형 있게 분산한다.
  const candidates=tokens.filter((t,idx)=>!selected.has(idx)).map((t,idx)=>{
    const lower=t.text.toLowerCase();
    const contentScore=stopWords.has(lower)?0:2;
    const lengthScore=Math.min(1.5,t.text.length/8);
    return {...t,contentScore,lengthScore};
  });
  const desired=[];
  const remaining=Math.max(0,target-selected.size);
  for(let k=0;k<remaining;k++){
    const ideal=(k+0.5)/Math.max(1,remaining);
    let best=null,bestScore=-Infinity;
    for(const c of candidates){
      if(desired.some(d=>d.index===c.index))continue;
      const pos=(c.index+0.5)/tokens.length;
      const distancePenalty=Math.abs(pos-ideal)*3;
      const adjacencyPenalty=[...selected,...desired.map(d=>d.index)].some(i=>Math.abs(i-c.index)===1)?0.35:0;
      const score=c.contentScore+c.lengthScore-distancePenalty-adjacencyPenalty;
      if(score>bestScore){bestScore=score;best=c;}
    }
    if(best){desired.push(best);selected.add(best.index);}
  }

  let html='';
  let cursor=0;
  tokens.forEach((t,idx)=>{
    if(t.start>cursor)html+=recallEscape(text.slice(cursor,t.start));
    if(selected.has(idx)){
      const isWord=overlaps(t,wordRanges);
      const isBasePattern=overlaps(t,patternRanges);
      const isExtraPattern=overlaps(t,extraPatternRanges);
      const blankClass=isBasePattern?'basePatternBlank':(isExtraPattern?'extraPatternBlank':(isWord?'wordBlank':'defaultBlank'));
      html+=blankWordsHtml(text.slice(t.start,t.end),blankClass);
    }else{
      html+=recallEscape(text.slice(t.start,t.end));
    }
    cursor=t.end;
  });
  if(cursor<text.length)html+=recallEscape(text.slice(cursor));
  return html||recallEscape(text);
}

function sentenceHighlightedHtml(q){
  const text=sentenceText(q);
  if(!text)return '<span class="patternEmpty">등록된 학습 문장이 없습니다.</span>';
  const pattern=sentencePattern(q);
  const word=recallText(q?.word||'').trim();
  const practicePatterns=q?.isPracticeSentence&&Array.isArray(q.practicePatterns)?q.practicePatterns.filter(Boolean):[];
  const practiceExtraSurfaces=q?.isPracticeSentence&&Array.isArray(q.practiceExtraPatternSurfaces)?q.practiceExtraPatternSurfaces.filter(Boolean):[];
  const practiceWords=q?.isPracticeSentence&&Array.isArray(q.targetWords)?q.targetWords.filter(Boolean):[];
  const patternRanges=q?.isPracticeSentence?practicePatterns.flatMap(x=>collectFlexiblePracticePatternRanges(text,x)):(pattern?collectHighlightRanges(text,pattern):[]);
  const extraPatternRanges=q?.isPracticeSentence?practiceExtraSurfaces.flatMap(x=>collectHighlightRanges(text,x)):[];
  const wordRanges=q?.isPracticeSentence?practiceWords.flatMap(x=>collectHighlightRanges(text,x)):(word?collectHighlightRanges(text,word):[]);
  const points=new Set([0,text.length]);
  [...patternRanges,...extraPatternRanges,...wordRanges].forEach(([a,b])=>{points.add(a);points.add(b)});
  const cuts=[...points].sort((a,b)=>a-b);
  let html='';
  for(let n=0;n<cuts.length-1;n++){
    const a=cuts[n],b=cuts[n+1];
    if(b<=a)continue;
    const part=recallEscape(text.slice(a,b));
    const inPattern=patternRanges.some(([x,y])=>a>=x&&b<=y);
    const inExtraPattern=extraPatternRanges.some(([x,y])=>a>=x&&b<=y);
    const inWord=wordRanges.some(([x,y])=>a>=x&&b<=y);
    if(inPattern)html+=`<span class="patternWord">${part}</span>`;
    else if(inWord)html+=`<span class="studyWord">${part}</span>`;
    else if(inExtraPattern)html+=`<span class="extraPatternWord">${part}</span>`;
    else html+=part;
  }
  return html||recallEscape(text);
}

async function speakSentenceOnce(q){
  const text=sentenceText(q);
  if(text)await speakComplete(text,getSpeechRate(),'en-US');
}
async function speakSentenceTwice(q){
  stopSpeech();
  if('speechSynthesis' in window)window.speechSynthesis.cancel();
  await speakSentenceOnce(q);
  await new Promise(r=>setTimeout(r,420));
  if(quizMode==='sentence'&&quizCurrent===q)await speakSentenceOnce(q);
}


// ===== V5.3.110 · 문장 말하기 3단계 녹음/비교 =====
let sentenceRecordingRecorder=null;
let sentenceRecordingStream=null;
let sentenceRecordingChunks=[];
let sentenceRecordingUrl='';
let sentenceRecordingStartedAt=0;
let sentenceRecordingDuration=0;
let sentenceRecordingTimer=null;
let sentenceRecordingQuestion=null;
let sentenceRecordingAudioCtx=null;
let sentenceRecordingAnalyser=null;
let sentenceRecordingSourceNode=null;
let sentenceRecordingWaveRAF=null;

function sentenceRecordingTime(sec){
  sec=Math.max(0,Math.round(Number(sec)||0));
  return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;
}
function sentenceRecordingAvailable(){
  return !!(window.MediaRecorder&&navigator.mediaDevices&&navigator.mediaDevices.getUserMedia);
}
function sentenceRecordingMime(){
  if(!window.MediaRecorder)return '';
  const types=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'];
  return types.find(t=>{try{return MediaRecorder.isTypeSupported(t)}catch(e){return false}})||'';
}

function sentenceRecordingStopWave(){
  if(sentenceRecordingWaveRAF){cancelAnimationFrame(sentenceRecordingWaveRAF);sentenceRecordingWaveRAF=null;}
  try{if(sentenceRecordingSourceNode)sentenceRecordingSourceNode.disconnect();}catch(e){}
  sentenceRecordingSourceNode=null;
  sentenceRecordingAnalyser=null;
  if(sentenceRecordingAudioCtx){
    try{sentenceRecordingAudioCtx.close();}catch(e){}
    sentenceRecordingAudioCtx=null;
  }
}
function sentenceRecordingStartWave(stream){
  try{
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)return;

    sentenceRecordingAudioCtx=new AC();
    sentenceRecordingAnalyser=sentenceRecordingAudioCtx.createAnalyser();
    sentenceRecordingAnalyser.fftSize=1024;
    sentenceRecordingAnalyser.smoothingTimeConstant=.9;
    sentenceRecordingSourceNode=sentenceRecordingAudioCtx.createMediaStreamSource(stream);
    sentenceRecordingSourceNode.connect(sentenceRecordingAnalyser);

    const data=new Uint8Array(sentenceRecordingAnalyser.fftSize);

    // raw waveform 대신 "말소리 크기(envelope)"를 누적해서 보여준다.
    // 작은 배경 소음은 noise gate로 제거하고, 말할 때만 부드럽게 봉우리가 생긴다.
    const history=[];
    const HISTORY_SIZE=54;
    let displayedLevel=0;
    let lastSampleAt=0;

    const roundedRect=(ctx,x,y,w,h,r)=>{
      const rr=Math.min(r,w/2,h/2);
      ctx.beginPath();
      ctx.moveTo(x+rr,y);
      ctx.arcTo(x+w,y,x+w,y+h,rr);
      ctx.arcTo(x+w,y+h,x,y+h,rr);
      ctx.arcTo(x,y+h,x,y,rr);
      ctx.arcTo(x,y,x+w,y,rr);
      ctx.closePath();
    };

    const draw=now=>{
      const canvas=document.getElementById('sentenceWaveCanvas');
      const meter=document.getElementById('sentenceVolumeMeter');
      const segments=document.querySelectorAll('.sentenceVolumeSegment');

      if(!sentenceRecordingAnalyser)return;

      sentenceRecordingAnalyser.getByteTimeDomainData(data);

      let sum=0;
      for(let i=0;i<data.length;i++){
        const v=(data[i]-128)/128;
        sum+=v*v;
      }

      const rms=Math.sqrt(sum/data.length);

      // 약한 상시 노이즈 제거: 일반적인 모바일 마이크의 바닥 노이즈는 거의 0으로 보이게 한다.
      const noiseFloor=.018;
      let voice=Math.max(0,rms-noiseFloor);

      // 말소리 크기를 보기 좋은 범위로 확장하되 과도한 움직임은 제한.
      voice=Math.min(1,voice*9.2);

      // 빠르게 올라가고 천천히 내려오는 미터 동작.
      const attack=.32;
      const release=.10;
      displayedLevel += (voice-displayedLevel) * (voice>displayedLevel?attack:release);

      // 70ms마다 한 점만 저장해 화면이 떨리지 않도록 한다.
      if(!lastSampleAt || now-lastSampleAt>=70){
        let sample=displayedLevel;

        // 아주 작은 값은 아예 평평하게 처리.
        if(sample<.055)sample=0;

        history.push(sample);
        if(history.length>HISTORY_SIZE)history.shift();
        lastSampleAt=now;
      }

      const pct=Math.round(displayedLevel*100);
      if(meter)meter.setAttribute('aria-valuenow',String(pct));

      // 볼륨은 길게 이어진 bar 대신 28개의 pill segment로 표시.
      const activeCount=Math.round(displayedLevel*28);
      segments.forEach((seg,i)=>{
        seg.classList.toggle('active',i<activeCount);
        seg.classList.toggle('hot',i>=21&&i<activeCount);
      });

      if(canvas){
        const rect=canvas.getBoundingClientRect();
        const dpr=Math.min(2,window.devicePixelRatio||1);
        const w=Math.max(1,Math.floor(rect.width*dpr));
        const h=Math.max(1,Math.floor(rect.height*dpr));
        if(canvas.width!==w||canvas.height!==h){
          canvas.width=w;
          canvas.height=h;
        }

        const ctx=canvas.getContext('2d');
        ctx.clearRect(0,0,w,h);

        const mid=h/2;

        // 아주 은은한 중앙선
        ctx.strokeStyle='rgba(244,114,182,.17)';
        ctx.lineWidth=1*dpr;
        ctx.setLineDash([2*dpr,4*dpr]);
        ctx.beginPath();
        ctx.moveTo(8*dpr,mid);
        ctx.lineTo(w-8*dpr,mid);
        ctx.stroke();
        ctx.setLineDash([]);

        // 중앙 정렬된 매끄러운 음성 봉우리.
        // 삼성 녹음기처럼 "말한 덩어리"만 보이고 잔노이즈는 거의 드러나지 않는다.
        const count=HISTORY_SIZE;
        const gap=2.7*dpr;
        const barW=Math.max(1.5*dpr,(w-28*dpr-gap*(count-1))/count);
        const maxAmp=h*.41;
        const minAmp=1.2*dpr;
        const startX=(w-(barW*count+gap*(count-1)))/2;

        for(let i=0;i<count;i++){
          const value=history[Math.max(0,history.length-count+i)]||0;

          // 이웃값과 살짝 섞어 spike를 둥글게.
          const prev=history[Math.max(0,history.length-count+i-1)]||0;
          const next=history[Math.max(0,history.length-count+i+1)]||0;
          const smooth=value*.58+prev*.21+next*.21;

          const amp=smooth<=0 ? minAmp : Math.max(minAmp, Math.pow(smooth,.72)*maxAmp);
          const x=startX+i*(barW+gap);
          const y=mid-amp;

          const alpha=smooth<=0 ? .22 : Math.min(.96,.45+smooth*.55);
          ctx.fillStyle=`rgba(244,63,94,${alpha})`;

          roundedRect(ctx,x,y,barW,amp*2,barW/2);
          ctx.fill();
        }
      }

      sentenceRecordingWaveRAF=requestAnimationFrame(draw);
    };

    sentenceRecordingWaveRAF=requestAnimationFrame(draw);
  }catch(e){}
}
function sentenceRecordingStopTracks(){
  sentenceRecordingStopWave();
  if(sentenceRecordingTimer){clearInterval(sentenceRecordingTimer);sentenceRecordingTimer=null;}
  if(sentenceRecordingStream){
    sentenceRecordingStream.getTracks().forEach(t=>{try{t.stop()}catch(e){}});
    sentenceRecordingStream=null;
  }
}
function sentenceRecordingReset(){
  if(sentenceRecordingRecorder&&sentenceRecordingRecorder.state==='recording'){
    try{sentenceRecordingRecorder.stop()}catch(e){}
  }
  sentenceRecordingStopTracks();
  sentenceRecordingRecorder=null;
  sentenceRecordingChunks=[];
  sentenceRecordingQuestion=null;
  sentenceRecordingDuration=0;
  if(sentenceRecordingUrl){URL.revokeObjectURL(sentenceRecordingUrl);sentenceRecordingUrl='';}
}
function sentenceRecordingToast(msg){
  let el=document.getElementById('sentenceRecordingToast');
  if(!el){el=document.createElement('div');el.id='sentenceRecordingToast';el.className='sentenceRecordingToast';document.body.appendChild(el);}
  el.textContent=msg;el.classList.add('show');
  clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),2200);
}
