// 퀴즈 화면 좌우 스와이프: 왼쪽은 다음 문제, 오른쪽은 이전 문제.
(function enableQuizSwipeNavigation(){
  const quizEl=document.getElementById('quiz');
  if(!quizEl||quizEl.dataset.swipeReady==='1')return;
  quizEl.dataset.swipeReady='1';
  let sx=0,sy=0,dx=0,dy=0,tracking=false,horizontal=false;
  const isInteractive=target=>!!target?.closest('button,select,input,textarea,a,[role="button"],.compareSheet,.drawerPanel');
  quizEl.addEventListener('touchstart',e=>{
    if(e.touches.length!==1||isInteractive(e.target))return;
    sx=e.touches[0].clientX;sy=e.touches[0].clientY;dx=0;dy=0;tracking=true;horizontal=false;
  },{passive:true});
  quizEl.addEventListener('touchmove',e=>{
    if(!tracking||e.touches.length!==1)return;
    dx=e.touches[0].clientX-sx;dy=e.touches[0].clientY-sy;
    if(!horizontal){
      if(Math.abs(dy)>Math.abs(dx)+8){tracking=false;return}
      if(Math.abs(dx)<12)return;
      horizontal=true;
    }
    if(horizontal)e.preventDefault();
  },{passive:false});
  quizEl.addEventListener('touchend',()=>{
    if(!tracking||!horizontal)return;
    const threshold=Math.min(80,Math.max(55,quizEl.clientWidth*.12));
    if(Math.abs(dx)>=threshold&&Math.abs(dx)>Math.abs(dy)*1.25){
      if(dx<0)goToNextQuizQuestion();
      else $('prevq')?.click();
    }
    tracking=false;horizontal=false;dx=dy=0;
  },{passive:true});
  quizEl.addEventListener('touchcancel',()=>{tracking=false;horizontal=false;dx=dy=0},{passive:true});
})();


