// v5.3.80 Daily study time tracking
const STUDY_TIME_KEY='myVocaStudyTimeV1';let studyRangeDays=7;let studyLastActivity=Date.now();
function studyDateKey(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function loadStudyTime(){try{return JSON.parse(localStorage.getItem(STUDY_TIME_KEY)||'{}')||{}}catch(e){return {}}}
function saveStudyTime(v){try{localStorage.setItem(STUDY_TIME_KEY,JSON.stringify(v))}catch(e){}}
function currentStudyCategory(){const day=$('dayAppPage');if(!day||day.classList.contains('hidden'))return null;if(document.body.classList.contains('practiceReadingMode'))return 'reading';const quiz=$('quiz');if(quiz&&!quiz.classList.contains('hidden'))return 'quiz';const learn=$('learn');if(learn&&!learn.classList.contains('hidden'))return 'word';return null}
function markStudyActivity(){studyLastActivity=Date.now()}
['pointerdown','keydown','touchstart','wheel'].forEach(ev=>document.addEventListener(ev,markStudyActivity,{passive:true}));
setInterval(()=>{if(document.hidden||Date.now()-studyLastActivity>180000)return;const cat=currentStudyCategory();if(!cat)return;const data=loadStudyTime(),key=studyDateKey(),row=data[key]||{word:0,reading:0,quiz:0};row[cat]=(Number(row[cat])||0)+10;data[key]=row;saveStudyTime(data)},10000);
function studySecondsForRow(r){return (Number(r?.word)||0)+(Number(r?.reading)||0)+(Number(r?.quiz)||0)}
function fmtStudy(sec){const mins=Math.floor(Math.max(0,sec||0)/60),h=Math.floor(mins/60),m=mins%60;return h?`${h}시간 ${m?m+'분':''}`:`${mins}분`}
function studyLastDates(n){const a=[],now=new Date();for(let i=n-1;i>=0;i--){const d=new Date(now);d.setHours(12,0,0,0);d.setDate(d.getDate()-i);a.push(d)}return a}
function currentWeekDates(){const now=new Date();now.setHours(12,0,0,0);const dow=(now.getDay()+6)%7,mon=new Date(now);mon.setDate(now.getDate()-dow);return Array.from({length:dow+1},(_,i)=>{const d=new Date(mon);d.setDate(mon.getDate()+i);return d})}
function calcStudyStreak(data){let best=0,run=0;for(let i=365;i>=0;i--){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-i);const active=studySecondsForRow(data[studyDateKey(d)])>=60;run=active?run+1:0;best=Math.max(best,run)}let streak=0;for(let i=0;i<366;i++){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-i);if(studySecondsForRow(data[studyDateKey(d)])>=60)streak++;else if(i>0)break}return {streak,best}}
function renderStudyTimeDashboard(){if(!$('studyTimeDashboard'))return;const data=loadStudyTime(),today=studyDateKey(),todaySec=studySecondsForRow(data[today]),weekSec=currentWeekDates().reduce((s,d)=>s+studySecondsForRow(data[studyDateKey(d)]),0),st=calcStudyStreak(data);$('studyTodayValue').textContent=fmtStudy(todaySec);$('studyWeekValue').textContent=fmtStudy(weekSec);$('studyStreakValue').textContent=st.streak+'일';$('studyBestStreak').textContent='최고 '+st.best+'일';const dates=studyLastDates(studyRangeDays),vals=dates.map(d=>studySecondsForRow(data[studyDateKey(d)])),max=Math.max(60,...vals),avg=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0;$('studyChartAverage').textContent=`${studyRangeDays}일 평균 ${fmtStudy(avg)}`;$('studyCategoryRangeLabel').textContent=studyRangeDays+'일';$('studyBarChart').innerHTML=dates.map((d,i)=>{const sec=vals[i],pct=Math.max(sec?3:1,Math.min(100,sec/max*100)),lbl=studyRangeDays===7?`${d.getMonth()+1}/${d.getDate()}`:`${d.getDate()}`;return `<div class="studyBarCol ${studyDateKey(d)===today?'today':''}"><span class="studyBarValue">${sec>=60?Math.round(sec/60)+'분':''}</span><div class="studyBar" style="height:${pct}%"></div><span class="studyBarLabel">${lbl}</span></div>`}).join('');const sums={word:0,reading:0,quiz:0};dates.forEach(d=>{const r=data[studyDateKey(d)]||{};Object.keys(sums).forEach(k=>sums[k]+=Number(r[k])||0)});const total=sums.word+sums.reading+sums.quiz,p=k=>total?Math.round(sums[k]/total*100):0,pw=p('word'),pr=p('reading'),pq=Math.max(0,100-pw-pr);$('studyCategoryTotal').textContent=fmtStudy(total);$('studyCatWord').textContent=`${fmtStudy(sums.word)} (${pw}%)`;$('studyCatReading').textContent=`${fmtStudy(sums.reading)} (${pr}%)`;$('studyCatQuiz').textContent=`${fmtStudy(sums.quiz)} (${pq}%)`;$('studyDonut').style.background=total?`conic-gradient(#6d4ce8 0 ${pw}%,#4b88e8 ${pw}% ${pw+pr}%,#61c781 ${pw+pr}% 100%)`:'conic-gradient(#e5e7eb 0 100%)'}
function setStudyRange(n){studyRangeDays=n;$('studyRange7')?.classList.toggle('active',n===7);$('studyRange30')?.classList.toggle('active',n===30);renderStudyTimeDashboard()}
document.addEventListener('click',e=>{if(e.target?.id==='studyRange7')setStudyRange(7);if(e.target?.id==='studyRange30')setStudyRange(30);if(e.target?.id==='studyTimeGuideBtn')alert('학습 시간은 화면이 보이고 최근 3분 안에 조작이 있었던 학습 화면에서만 기록됩니다.\\n\\n단어 학습 / 실전 리딩 / 퀴즈·문장 말하기로 나누어 이 기기의 localStorage에 저장됩니다.')});

function masteryScore(w){
  let s=stats[w.word];
  if((s.studyCount||0)===0)return 0;

  let quizAttempts=(s.quizCorrect||0)+(s.quizWrong||0);
  let quizPart=quizAttempts?30*((s.quizCorrect||0)/quizAttempts):0;

  let reviewPart=30*Math.min((s.reviewStep||0)/5,1);
  let studyPart=15*Math.min((s.studyCount||0)/5,1);

  let errors=(s.quizWrong||0);
  let resiliencePart=15*Math.max(0,1-errors/8);

  let recencyPart=0;
  if(s.dueAt){
    recencyPart=s.dueAt>Date.now()?10:4;
  }else if((s.studyCount||0)>0){
    recencyPart=3;
  }

  return Math.max(0,Math.min(100,Math.round(quizPart+reviewPart+studyPart+resiliencePart+recencyPart)));
}
function scoreGrade(score){
  if(score>=90)return {label:'Master',cls:'gradeBlue',short:'blue'};
  if(score>=75)return {label:'안정',cls:'gradeGreen',short:'green'};
  if(score>=50)return {label:'학습 중',cls:'gradeYellow',short:'yellow'};
  if(score>=25)return {label:'취약',cls:'gradeOrange',short:'orange'};
  return {label:'집중 필요',cls:'gradeRed',short:'red'};
}
function renderScore(){
  stopAllReadingForNavigation();
  renderStudyTimeDashboard();
  let rows=W.map(w=>({w,score:masteryScore(w)}));
  let learned=rows.filter(x=>stats[x.w.word].studyCount>0);
  let avg=learned.length?Math.round(learned.reduce((a,x)=>a+x.score,0)/learned.length):0;
  let grade=scoreGrade(avg);

  $('dayScore').textContent=avg;
  $('dayScoreGrade').textContent=grade.label;
  $('dayScoreGrade').className='scoreGrade '+grade.cls;

  $('bandMaster').textContent=rows.filter(x=>x.score>=90).length;
  $('bandStable').textContent=rows.filter(x=>x.score>=75&&x.score<90).length;
  $('bandLearning').textContent=rows.filter(x=>x.score>=50&&x.score<75).length;
  $('bandWeak').textContent=rows.filter(x=>x.score>=25&&x.score<50).length;
  $('bandFocus').textContent=rows.filter(x=>x.score<25).length;

  let qc=W.reduce((a,w)=>a+(stats[w.word].quizCorrect||0),0);
  let qw=W.reduce((a,w)=>a+(stats[w.word].quizWrong||0),0);
  $('scoreQuizRate').textContent=(qc+qw)?Math.round(qc/(qc+qw)*100)+'%':'0%';
  $('scoreLearnedCount').textContent=learned.length;
  $('scoreReviewStage').textContent=learned.length?(learned.reduce((a,x)=>a+(stats[x.w.word].reviewStep||0),0)/learned.length).toFixed(1):'0.0';

  let focus=rows.filter(x=>x.score<50 && stats[x.w.word].studyCount>0);
  $('focusStudyBtn').textContent=focus.length?`🔥 50점 미만 집중 학습 ${focus.length}개`:'🎉 50점 미만 학습 단어 없음';
  $('focusStudyBtn').disabled=!focus.length;

  let sort=$('scoreSort').value;
  if(sort==='low')rows.sort((a,b)=>a.score-b.score);
  if(sort==='high')rows.sort((a,b)=>b.score-a.score);
  if(sort==='wrong')rows.sort((a,b)=>(stats[b.w.word].quizWrong||0)-(stats[a.w.word].quizWrong||0));
  if(sort==='studyAsc')rows.sort((a,b)=>stats[a.w.word].studyCount-stats[b.w.word].studyCount||a.score-b.score);
  if(sort==='alpha')rows.sort((a,b)=>a.w.word.localeCompare(b.w.word));

  $('scoreList').innerHTML=rows.map(x=>{
    let w=x.w,s=stats[w.word],g=scoreGrade(x.score);
    let qa=(s.quizCorrect||0)+(s.quizWrong||0);
    let qr=qa?Math.round((s.quizCorrect||0)/qa*100):0;
    return `<div class="scoreItem">
      <div class="scoreItemTop">
        <div><div class="scoreWord">${w.word}</div><div class="scoreMeaning">${w.meaning}</div></div>
        <div class="wordScore ${g.short}">${x.score}</div>
      </div>
      <div class="scoreBreakdown">
        <span>학습 ${s.studyCount||0}회</span>
        <span>퀴즈 ${qr}%</span>
        <span>퀴즈 정답 ${s.quizCorrect||0}회</span><span>퀴즈 오답 ${s.quizWrong||0}회</span><span>연속 정답 ${s.quizStreak||0}회</span>
        <span>복습 단계 ${s.reviewStep||0}</span>
      </div>
    </div>`;
  }).join('');
}
