// Single-file deployment: remove old service workers/caches so index.html is always the source of truth.
if('serviceWorker' in navigator){
  window.addEventListener('load',async()=>{
    try{
      const regs=await navigator.serviceWorker.getRegistrations();
      await Promise.all(regs.map(r=>r.unregister()));
    }catch(e){}
    try{
      if('caches' in window){
        const keys=await caches.keys();
        await Promise.all(keys.map(k=>caches.delete(k)));
      }
    }catch(e){}
  });
}

function refreshUsageRecommendation(){
  const title=$('usageRecommendTitle'),list=$('usageRecommendList');
  if(!title||!list)return;
  const due=dueWordsAll().length;
  const weak=ALL_WORDS.filter(w=>(stats[w.word]?.quizWrong||0)>0).length;
  const favoriteCount=favs.length;
  let nextDay=1;
  for(let d=1;d<=currentCfg().days;d++){const p=dayProgress(d);if(p.learned<p.total){nextDay=d;break}}
  const items=[];
  if(due>0)items.push(`망각곡선에서 오늘 복습할 단어 ${due}개를 먼저 확인하세요.`);
  if(weak>0||favoriteCount>0)items.push(`홈에서 ‘틀린 단어 + 모르는 단어’를 선택해 오답 ${weak}개와 모르는 단어 ${favoriteCount}개를 집중 반복하세요.`);
  items.push(`DAY ${nextDay}의 ‘모르는 단어 선택’에서 전체 목록을 보고 모르는 단어를 먼저 체크하세요.`);
  items.push('마지막으로 단어 말하기 또는 문장 말하기를 10분 정도 진행하세요.');
  title.textContent=due>0?'오늘은 복습부터 시작하세요':(weak>0||favoriteCount>0?'취약 단어를 집중 학습하세요':`DAY ${nextDay} 새 학습을 시작하세요`);
  list.innerHTML=items.map(x=>`<li>${x}</li>`).join('');
}

