function hideStandalonePages(){['configPage','usagePage','comparePage'].forEach(id=>{const el=$(id);if(el)el.classList.add('hidden')})}
let configReturnState={page:'home',scrollY:0};
function captureConfigReturnState(){
  const home=$('homePage'),day=$('dayAppPage'),myclass=$('myClassPage');
  if(myclass&&!myclass.classList.contains('hidden'))return {page:'myclass',scrollY:window.scrollY||0};
  if(day&&!day.classList.contains('hidden'))return {page:'day',scrollY:window.scrollY||0};
  if(home&&!home.classList.contains('hidden'))return {page:'home',scrollY:window.scrollY||0};
  return configReturnState||{page:'home',scrollY:0};
}
function restoreConfigReturnState(){
  const state=configReturnState||{page:'home',scrollY:0};
  $('configPage')?.classList.add('hidden');
  if(state.page==='myclass'){
    $('homePage')?.classList.add('hidden');$('dayAppPage')?.classList.add('hidden');$('myClassPage')?.classList.remove('hidden');$('myClassBottom')?.classList.remove('hidden');
  }else if(state.page==='day'){
    $('myClassPage')?.classList.add('hidden');$('myClassBottom')?.classList.add('hidden');$('homePage')?.classList.add('hidden');$('dayAppPage')?.classList.remove('hidden');
  }else{
    $('myClassPage')?.classList.add('hidden');$('myClassBottom')?.classList.add('hidden');$('dayAppPage')?.classList.add('hidden');$('homePage')?.classList.remove('hidden');
  }
  requestAnimationFrame(()=>window.scrollTo({top:Number(state.scrollY)||0,behavior:'auto'}));
}
