if($('configResetBtn'))$('configResetBtn').onclick=()=>{appSettings={...APP_SETTINGS_DEFAULTS};localStorage.setItem(APP_SETTINGS_KEY,JSON.stringify(appSettings));setSpeechRate(appSettings.speechRate);fillConfigurationForm();syncContinuousStudyRepeatControl();refreshHomeConfigSummary()};

