  function open(word){const w=typeof word==='string'?findWord(word):word;if(!w)return;render(w);document.body.classList.add('compare-sheet-open');backdrop.classList.add('open');sheet.classList.add('open')}
  function close(){document.body.classList.remove('compare-sheet-open');backdrop.classList.remove('open');sheet.classList.remove('open');sheet.style.transform='';sheet.classList.remove('dragging')}
  window.openQuickCompare=open;window.closeQuickCompare=close;
