window.exportMyVocaLearningRecords=function(){
  try{
    if(typeof save==='function')save();
    const all=Array.isArray(ALL_WORDS)?ALL_WORDS:[];
    const unknown=[...new Set(Array.isArray(favs)?favs:[])];
    const wrong=all.filter(w=>Number(stats?.[w.word]?.quizWrong||0)>0).map(w=>w.word);
    const words=[...new Set([...unknown,...wrong])];
    const records=words.map(word=>{
      const w=all.find(x=>x.word===word)||{};
      const s=stats?.[word]||{};
      return {
        word,meaning:w.meaning||w.ko||'',day:Number(w.newDay||0),day_no:Number(w.newNo||0),
        is_unknown:unknown.includes(word),is_wrong:Number(s.quizWrong||0)>0,
        quiz_wrong_count:Number(s.quizWrong||0),quiz_correct_count:Number(s.quizCorrect||0),
        study_count:Number(s.studyCount||0),last_seen:Number(s.lastSeen||0),
        last_quiz_wrong:Number(s.lastQuizWrong||0),review_step:Number(s.reviewStep||0)
      };
    });
    const payload={schema_version:'MY_VOCA_LEARNING_RECORD_V2',app_version:'5.3.25',exported_at:new Date().toISOString(),
      wrong_words:wrong,unknown_words:unknown,records};
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});
    const a=document.createElement('a'),d=new Date();
    a.href=URL.createObjectURL(blob);
    a.download='MY_VOCA_LEARNING_RECORD_'+d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')+'.json';
    document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},400);
  }catch(e){console.error(e);alert('학습 기록 내보내기에 실패했습니다.');}
};


