    if(!sec||document.getElementById('cfgMyClassFullRepeat'))return;
    const row=document.createElement('div');row.className='configRow';
    row.innerHTML='<div class="configCopy"><b>전체 3화면 연속 반복</b><span>핵심 교정 → Chunk → 말하기를 차례로 재생한 뒤 다시 처음부터 반복합니다. 기본 ON입니다.</span></div><input id="cfgMyClassFullRepeat" class="configCheck" type="checkbox">';
    const notice=sec.querySelector('.configNotice');sec.insertBefore(row,notice||null);
