      const btn=$('quizAllWrongBtn'),label=$('quizDayLabel');if(!btn||!label)return;
      btn.disabled=true;btn.classList.remove('active');btn.textContent='MY 수업 문장 학습';
      const count=myClassSentenceCards(V534.myQuizLesson).length;
      label.innerHTML=`<b>MY 수업 ${V534.myQuizLesson}</b><span>${count}문장 · ${MY_CLASS_META[V534.myQuizLesson]?.title||''}</span>`;
      $('quizPrevDay').disabled=V534.myQuizLesson<=1;$('quizNextDay').disabled=V534.myQuizLesson>=lessonCount();updateQuizFilterCount();return;
