function m536PatternRows(lesson,text){
  const rows=[];
  for(const [label,ko,re] of (M536_PATTERNS[lesson]||[])){
    const m=String(text||'').match(re);
    if(m)rows.push({label,ko,surface:m[0]});
  }
  return rows.filter((x,i,a)=>a.findIndex(y=>y.label===x.label)===i);
}
function m536EnrichCard(q,lesson){
  const rows=m536PatternRows(Number(lesson),q.example||'');
  const existing=new Set([...(q.practicePatterns||[]),...(q.practiceExtraPatterns||[])]);
  q.practicePatterns=Array.isArray(q.practicePatterns)?q.practicePatterns:[];
  q.practicePatternMeanings=Array.isArray(q.practicePatternMeanings)?q.practicePatternMeanings:[];
  q.practiceExtraPatterns=Array.isArray(q.practiceExtraPatterns)?q.practiceExtraPatterns:[];
  q.practiceExtraPatternMeanings=Array.isArray(q.practiceExtraPatternMeanings)?q.practiceExtraPatternMeanings:[];
  q.practiceExtraPatternSurfaces=Array.isArray(q.practiceExtraPatternSurfaces)?q.practiceExtraPatternSurfaces:[];
  rows.forEach(r=>{
    if(existing.has(r.label))return;
    q.practiceExtraPatterns.push(r.label);
    q.practiceExtraPatternMeanings.push(r.ko);
    q.practiceExtraPatternSurfaces.push(r.surface);
    existing.add(r.label);
  });
  return q;
}

// 이전 v5.3.95의 자동 패턴 탐색 결과까지 유지하면서 누락 패턴을 추가한다.
const m536PrevCards=window.myClassSentenceCards;
if(typeof m536PrevCards==='function'){
  window.myClassSentenceCards=function(lessonNo){
    return m536PrevCards(lessonNo).map(q=>m536EnrichCard(q,lessonNo));
  };
  try{myClassSentenceCards=window.myClassSentenceCards}catch(e){}
}

